import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../data/stock_count_repository.dart';
import '../domain/stock_movement.dart';
import 'stock_count_report.dart';

// Only recognize the complete text generated by the old counting flow. A
// manually entered reference or a personalized note must keep its original text.
String? _legacyCountId(StockMovement movement) {
  const prefix = 'Contagem ';
  final reference = movement.operationReference.trim();
  if (movement.type != StockMovementType.adjustment ||
      !reference.startsWith(prefix)) {
    return null;
  }
  final candidate = reference.substring(prefix.length);
  if (!RegExp(r'^[A-Za-z0-9]{20}$').hasMatch(candidate) ||
      movement.note.trim() != 'Ajuste gerado pela contagem $candidate.') {
    return null;
  }
  return candidate;
}

String? stockCountMovementId(StockMovement movement) =>
    movement.stockCountId ?? _legacyCountId(movement);

String stockCountMovementReference(StockMovement movement) {
  final countId = stockCountMovementId(movement);
  if (countId == null) return movement.operationReference;
  final reference = movement.operationReference.trim();
  if (reference == 'Contagem' || reference == 'Contagem $countId') {
    return movement.stockCountCode == null
        ? 'Contagem'
        : 'Contagem ${movement.stockCountCode}';
  }
  return movement.operationReference;
}

String stockCountMovementNote(StockMovement movement) {
  final countId = stockCountMovementId(movement);
  final note = movement.note.trim();
  if (countId != null &&
      (note == 'Ajuste gerado pela contagem $countId.' ||
          note == 'Ajuste gerado pela contagem.')) {
    return movement.stockCountCode == null
        ? 'Ajuste gerado pela contagem.'
        : 'Ajuste gerado pela contagem ${movement.stockCountCode}.';
  }
  return movement.note;
}

/// Opens the count report without exposing the technical Firestore identifier.
class StockCountMovementReference extends ConsumerStatefulWidget {
  const StockCountMovementReference({
    super.key,
    required this.movement,
    this.prefix = '',
    this.style,
  });

  final StockMovement movement;
  final String prefix;
  final TextStyle? style;

  @override
  ConsumerState<StockCountMovementReference> createState() =>
      _StockCountMovementReferenceState();
}

class _StockCountMovementReferenceState
    extends ConsumerState<StockCountMovementReference> {
  bool _loading = false;

  @override
  Widget build(BuildContext context) {
    final reference = stockCountMovementReference(widget.movement).trim();
    final label =
        '${widget.prefix}${reference.isEmpty ? 'Não informada' : reference}';
    if (stockCountMovementId(widget.movement) == null) {
      return Text(
        label,
        style: widget.style,
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
      );
    }

    return Align(
      alignment: Alignment.centerLeft,
      child: TextButton(
        onPressed: _loading ? null : _openReport,
        style: TextButton.styleFrom(
          padding: const EdgeInsets.symmetric(vertical: 6),
          minimumSize: const Size(0, 36),
          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
          alignment: Alignment.centerLeft,
        ),
        child: _loading
            ? const SizedBox.square(
                dimension: 18,
                child: CircularProgressIndicator(strokeWidth: 2),
              )
            : Text(label, maxLines: 2, overflow: TextOverflow.ellipsis),
      ),
    );
  }

  Future<void> _openReport() async {
    final movement = widget.movement;
    final countId = stockCountMovementId(movement);
    if (countId == null) return;
    setState(() => _loading = true);
    try {
      final count = await ref
          .read(stockCountRepositoryProvider)
          .findById(movement.companyId, countId);
      if (!mounted) return;
      if (count == null) {
        _showError('O relatório desta contagem não foi encontrado.');
        return;
      }
      setState(() => _loading = false);
      await showStockCountReport(context, count);
    } catch (_) {
      if (mounted) {
        _showError('Não foi possível abrir o relatório. Tente novamente.');
      }
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _showError(String message) {
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text(message)));
  }
}
